-- Fresh Crazy Responses schema. Use a NEW Supabase project or back up before running.
create extension if not exists pgcrypto;
create table if not exists public.cr_rooms(id uuid primary key default gen_random_uuid(),room_code text unique not null,room_name text not null,visibility text not null check(visibility in('public','private')),player_limit int not null check(player_limit between 3 and 10),round_count int not null check(round_count in(3,5,10)),prompt_style text not null,host_player_id uuid not null,status text not null default 'lobby',round_number int not null default 0,created_at timestamptz default now(),last_activity_at timestamptz default now());
create table if not exists public.cr_players(id uuid primary key default gen_random_uuid(),room_id uuid references public.cr_rooms on delete cascade,player_id uuid not null,player_name text not null,is_active boolean default true,is_spectator boolean default false,joined_at timestamptz default now(),last_seen_at timestamptz default now(),unique(room_id,player_id));
create table if not exists public.cr_rounds(id uuid primary key default gen_random_uuid(),room_id uuid references public.cr_rooms on delete cascade,round_number int,phase text,prompt_text text,deadline_at timestamptz,unique(room_id,round_number));
create table if not exists public.cr_responses(id uuid primary key default gen_random_uuid(),round_id uuid references public.cr_rounds on delete cascade,player_id uuid,player_name text,answer_text text,edited boolean default false,unique(round_id,player_id));
create table if not exists public.cr_votes(id uuid primary key default gen_random_uuid(),round_id uuid references public.cr_rounds on delete cascade,response_id uuid references public.cr_responses on delete cascade,voter_id uuid,created_at timestamptz default now(),unique(round_id,voter_id));
create table if not exists public.cr_chat(id uuid primary key default gen_random_uuid(),room_id uuid references public.cr_rooms on delete cascade,player_id uuid,player_name text,message text,created_at timestamptz default now());
create table if not exists public.cr_scores(player_id uuid,player_name text,points int default 0,round_wins int default 0,week_start date,primary key(player_id,week_start));
do $$ declare t text; begin foreach t in array array['cr_rooms','cr_players','cr_rounds','cr_responses','cr_votes','cr_chat','cr_scores'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end $$;
create or replace function public.cr_create_room(p_player_id uuid,p_player_name text,p_room_name text,p_visibility text,p_player_limit int,p_round_count int,p_prompt_style text) returns jsonb language plpgsql security definer set search_path=public as $$declare r cr_rooms; c text;begin if length(trim(p_player_name)) not between 1 and 20 then raise exception 'Name must be 1–20 characters';end if;if p_player_limit not between 3 and 10 or p_round_count not in(3,5,10) then raise exception 'Invalid settings';end if;c=upper(substr(encode(gen_random_bytes(4),'hex'),1,6));insert into cr_rooms(room_code,room_name,visibility,player_limit,round_count,prompt_style,host_player_id)values(c,left(trim(p_room_name),32),p_visibility,p_player_limit,p_round_count,p_prompt_style,p_player_id)returning * into r;insert into cr_players(room_id,player_id,player_name)values(r.id,p_player_id,trim(p_player_name));return jsonb_build_object('room_code',c);end$$;
create or replace function public.cr_join_room(p_room_code text,p_player_id uuid,p_player_name text) returns jsonb language plpgsql security definer set search_path=public as $$declare r cr_rooms;begin select * into r from cr_rooms where room_code=upper(trim(p_room_code)) for update;if not found then raise exception 'Room not found';end if;insert into cr_players(room_id,player_id,player_name,is_spectator)values(r.id,p_player_id,left(trim(p_player_name),20),r.status<>'lobby')on conflict(room_id,player_id)do update set is_active=true,last_seen_at=now(),player_name=excluded.player_name;if(select count(*) from cr_players where room_id=r.id and is_active and last_seen_at>now()-interval '90 seconds')>r.player_limit then delete from cr_players where room_id=r.id and player_id=p_player_id;raise exception 'Room is full';end if;return jsonb_build_object('room_code',r.room_code);end$$;
create or replace function public.cr_room_state(p_room_code text,p_player_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r cr_rooms;p jsonb;d jsonb;begin select * into r from cr_rooms where room_code=upper(p_room_code);if not found then return jsonb_build_object('room',null);end if;update cr_players set last_seen_at=now() where room_id=r.id and player_id=p_player_id and is_active;select coalesce(jsonb_agg(jsonb_build_object('player_id',player_id,'player_name',player_name,'is_spectator',is_spectator)),'[]') into p from cr_players where room_id=r.id and is_active and last_seen_at>now()-interval '90 seconds';select to_jsonb(x) into d from(select rr.id,rr.round_number,rr.phase,rr.prompt_text,rr.deadline_at,(select coalesce(jsonb_agg(jsonb_build_object('response_id',a.id,'player_id',a.player_id,'answer_text',a.answer_text)),'[]') from cr_responses a where a.round_id=rr.id and rr.phase='voting') answers,(select coalesce(jsonb_agg(jsonb_build_object('answer_text',a.answer_text,'votes',v.n)),'[]') from cr_responses a left join lateral(select count(*) n from cr_votes z where z.response_id=a.id)v on true where a.round_id=rr.id and rr.phase in('results','finished')) results from cr_rounds rr where rr.room_id=r.id order by round_number desc limit 1)x;return jsonb_build_object('room',to_jsonb(r),'players',p,'round',d);end$$;
create or replace function public.cr_public_rooms() returns table(room_code text,room_name text,player_count bigint,player_limit int,round_count int) language sql security definer set search_path=public as $$select r.room_code,r.room_name,count(p.id),r.player_limit,r.round_count from cr_rooms r left join cr_players p on p.room_id=r.id and p.is_active and p.last_seen_at>now()-interval '90 seconds' where r.visibility='public' and r.status='lobby' and r.last_activity_at>now()-interval '15 minutes' group by r.id order by r.created_at desc limit 50$$;
create or replace function public.cr_heartbeat(p_room_code text,p_player_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update cr_players p set last_seen_at=now() from cr_rooms r where p.room_id=r.id and r.room_code=upper(p_room_code) and p.player_id=p_player_id and p.is_active;update cr_rooms set last_activity_at=now() where room_code=upper(p_room_code);end$$;
create or replace function public.cr_leave_room(p_room_code text,p_player_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;h uuid;begin select * into r from cr_rooms where room_code=upper(p_room_code) for update;if not found then return;end if;update cr_players set is_active=false where room_id=r.id and player_id=p_player_id;select player_id into h from cr_players where room_id=r.id and is_active order by joined_at limit 1;if h is null then delete from cr_rooms where id=r.id;else update cr_rooms set host_player_id=case when host_player_id=p_player_id then h else host_player_id end where id=r.id;end if;end$$;
create or replace function public.cr_cleanup() returns void language plpgsql security definer set search_path=public as $$begin update cr_players set is_active=false where is_active and last_seen_at<now()-interval '90 seconds';update cr_rooms r set host_player_id=(select player_id from cr_players p where p.room_id=r.id and p.is_active order by joined_at limit 1) where r.host_player_id not in(select player_id from cr_players p where p.room_id=r.id and p.is_active);delete from cr_rooms r where not exists(select 1 from cr_players p where p.room_id=r.id and p.is_active);delete from cr_rooms where last_activity_at<now()-interval '24 hours';end$$;
create or replace function public.cr_start_game(p_room_code text,p_player_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;begin select * into r from cr_rooms where room_code=upper(p_room_code) for update;if r.host_player_id<>p_player_id then raise exception 'Host only';end if;if(select count(*) from cr_players where room_id=r.id and is_active and last_seen_at>now()-interval '90 seconds')<3 then raise exception 'At least 3 players required';end if;insert into cr_rounds(room_id,round_number,phase,prompt_text,deadline_at)values(r.id,1,'answering','The worst thing to hear from your GPS is ______.',now()+interval '60 seconds');update cr_rooms set status='answering',round_number=1 where id=r.id;end$$;
create or replace function public.cr_update_room(p_room_code text,p_player_id uuid,p_room_name text,p_visibility text,p_player_limit int,p_round_count int,p_prompt_style text) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;begin select * into r from cr_rooms where room_code=upper(p_room_code) for update;if r.host_player_id<>p_player_id or r.status<>'lobby' then raise exception 'Host only in lobby';end if;update cr_rooms set room_name=left(trim(p_room_name),32),visibility=p_visibility,player_limit=p_player_limit,round_count=p_round_count,prompt_style=p_prompt_style where id=r.id;end$$;
create or replace function public.cr_send_chat(p_room_code text,p_player_id uuid,p_message text) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;n text;begin select * into r from cr_rooms where room_code=upper(p_room_code);select player_name into n from cr_players where room_id=r.id and player_id=p_player_id and is_active;if n is null or r.status<>'lobby' then raise exception 'Chat unavailable';end if;insert into cr_chat(room_id,player_id,player_name,message)values(r.id,p_player_id,n,left(trim(p_message),240));end$$;
create or replace function public.cr_chat_history(p_room_code text) returns table(player_name text,message text) language sql security definer set search_path=public as $$select c.player_name,c.message from cr_chat c join cr_rooms r on r.id=c.room_id where r.room_code=upper(p_room_code) and r.status='lobby' order by c.created_at desc limit 40$$;
create or replace function public.cr_submit_answer(p_room_code text,p_player_id uuid,p_answer text) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;d cr_rounds;n text;begin select * into r from cr_rooms where room_code=upper(p_room_code);select * into d from cr_rounds where room_id=r.id order by round_number desc limit 1 for update;select player_name into n from cr_players where room_id=r.id and player_id=p_player_id and is_active and not is_spectator;if n is null or d.phase<>'answering' then raise exception 'Answering closed';end if;if trim(p_answer)='' then raise exception 'Answer is empty';end if;insert into cr_responses(round_id,player_id,player_name,answer_text)values(d.id,p_player_id,n,left(trim(p_answer),180))on conflict(round_id,player_id)do update set answer_text=excluded.answer_text,edited=true where cr_responses.edited=false;if(select count(*) from cr_responses where round_id=d.id)>=(select count(*) from cr_players where room_id=r.id and is_active and not is_spectator)then update cr_rounds set phase='voting',deadline_at=now()+interval '30 seconds' where id=d.id;update cr_rooms set status='voting' where id=r.id;end if;end$$;
create or replace function public.cr_vote(p_room_code text,p_player_id uuid,p_response_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;d cr_rounds;a cr_responses;begin select * into r from cr_rooms where room_code=upper(p_room_code);select * into d from cr_rounds where room_id=r.id order by round_number desc limit 1 for update;select * into a from cr_responses where id=p_response_id and round_id=d.id;if d.phase<>'voting' or a.player_id=p_player_id then raise exception 'Invalid vote';end if;insert into cr_votes(round_id,response_id,voter_id)values(d.id,p_response_id,p_player_id)on conflict(round_id,voter_id)do nothing;if(select count(*) from cr_votes where round_id=d.id)>=(select count(*) from cr_players where room_id=r.id and is_active and not is_spectator)then update cr_rounds set phase='results',deadline_at=now()+interval '15 seconds' where id=d.id;update cr_rooms set status='results' where id=r.id;end if;end$$;
create or replace function public.cr_next_round(p_room_code text,p_player_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;d cr_rounds;n int;begin select * into r from cr_rooms where room_code=upper(p_room_code) for update;if r.host_player_id<>p_player_id then raise exception 'Host only';end if;select * into d from cr_rounds where room_id=r.id order by round_number desc limit 1 for update;n=r.round_number+1;if n>r.round_count then update cr_rooms set status='finished' where id=r.id;update cr_rounds set phase='finished' where id=d.id;return;end if;update cr_players set is_spectator=false where room_id=r.id and is_active;insert into cr_rounds(room_id,round_number,phase,prompt_text,deadline_at)values(r.id,n,'answering','Nobody expected the town meeting to be about ______.',now()+interval '60 seconds');update cr_rooms set status='answering',round_number=n where id=r.id;end$$;
create or replace function public.cr_rematch(p_room_code text,p_player_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r cr_rooms;begin select * into r from cr_rooms where room_code=upper(p_room_code) for update;if r.host_player_id<>p_player_id then raise exception 'Host only';end if;delete from cr_rounds where room_id=r.id;update cr_players set is_spectator=false where room_id=r.id and is_active;update cr_rooms set status='lobby',round_number=0 where id=r.id;end$$;
create or replace function public.cr_weekly_leaderboard() returns table(player_name text,points int) language sql security definer set search_path=public as $$select player_name,points from cr_scores where week_start=date_trunc('week',now())::date order by points desc limit 10$$;
do $$declare f text;begin foreach f in array array['cr_create_room','cr_join_room','cr_room_state','cr_public_rooms','cr_heartbeat','cr_leave_room','cr_cleanup','cr_start_game','cr_update_room','cr_send_chat','cr_chat_history','cr_submit_answer','cr_vote','cr_next_round','cr_rematch','cr_weekly_leaderboard'] loop execute format('grant execute on function public.%I to anon,authenticated',f);end loop;end$$;
